def is_subsequence(s, t):
    t_iter = iter(t)
    return all(char in t_iter for char in s)

def min_cost_to_form_set(s, k):
    n = len(s)
    if n < k:
        return -1

    # Generate all possible subsequences of s
    subsequences = set()
    for i in range(1 << n):
        subseq = ''.join(s[j] for j in range(n) if i & (1 << j))
        subsequences.add(subseq)

    # Sort subsequences by length to minimize cost
    subsequences = sorted(subsequences, key=len)

    # Use a set to store the subsequences in S
    S = set()
    total_cost = 0

    for subseq in subsequences:
        if len(S) == k:
            break
        if subseq not in S:
            S.add(subseq)
            total_cost += n - len(subseq)

    if len(S) == k:
        return total_cost
    else:
        return -1

def main():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    k = int(data[1])
    s = data[2]

    result = min_cost_to_form_set(s, k)
    print(result)

