def calculate_cost(n, k, s):
    if k > n:
        return -1
    if k == n:
        return 0
    if k == 1:
        return n - 1

    cost = float('inf')
    for i in range(1, n):
        cost = min(cost, n - i + calculate_cost(n - i, k - 1, s[i:]))
    return cost

