def is_subsequence(s, t):
    it = iter(s)
    return all(c in it for c in t)

def min_cost_to_form_set(s, k):
    n = len(s)
    if k > n * (n + 1) // 2:
        return -1
    if k == 0:
        return 0

    # Generate all subsequences and their costs
    subsequences = []
    for i in range(1 << n):
        subseq = ''.join(s[j] for j in range(n) if i & (1 << j))
        subsequences.append((subseq, n - len(subseq)))

    subsequences.sort(key=lambda x: x[1])

    # Use a greedy approach to pick the cheapest subsequences
    selected = []
    for subseq, cost in subsequences:
        if len(selected) == k:
            break
        if subseq not in selected and all(not is_subsequence(subseq, x) for x in selected):
            selected.append(subseq)

    if len(selected) < k:
        return -1

    return sum(cost for _, cost in selected)

