import sys
from collections import defaultdict

def read_input():
    n, k = map(int, input().split())
    s = input().strip()
    return n, k, s

def is_subsequence(s, t):
    it = iter(s)
    return all(c in it for c in t)

def min_cost_to_form_set(n, k, s):
    if k > n:
        return -1
    if k == n:
        return 0

    # Calculate the cost of forming each subsequence of length i
    cost = defaultdict(int)
    for i in range(1, n + 1):
        for j in range(n - i + 1):
            t = s[j:j+i]
            cost[t] = n - i

    # Sort subsequences by cost
    sorted_cost = sorted(cost.items(), key=lambda x: x[1])

    # Select the k cheapest subsequences
    selected = [sorted_cost[i][0] for i in range(k)]

    # Check if the selected subsequences form a set
    if len(set(selected)) != k:
        return -1

    # Calculate the total cost
    total_cost = sum(cost[t] for t in selected)

    return total_cost

def main():
    n, k, s = read_input()
    result = min_cost_to_form_set(n, k, s)
    print(result)

if __name__ == "__main__":
    main()

