    if not segments:
        return 0
    segments.sort()
    left, right = segments[0]
    max_length = 0
    for l, r in segments[1:]:
        if l <= right:
            right = min(right, r)
            max_length = max(max_length, right - left)
        else:
            left, right = l, r
    return max_length

