    return len(set(s)) >= k

def min_cost_to_form_set(s, k):
    if not can_form_set(s, k):
        return -1

    n = len(s)
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(k + 1):
            dp[i][j] = dp[i - 1][j]  # Skip the current character
            for l in range(i):
                if s[l] == s[i - 1]:
                    dp[i][j] = min(dp[i][j], dp[l][j - 1] + (n - i + l))

