        factors[n] = 1
    return factors

def count_valid_decks(n, k, a):
    factors = calculate_factors(k)
    total_ways = 0

    for x in range(n):
        for y in range(n - x):
            product_factors = {}
            for i in range(x, n - y):
                card_factors = calculate_factors(a[i])
                for factor, count in card_factors.items():
                    if factor in product_factors:
                        product_factors[factor] += count
                    else:
                        product_factors[factor] = count
            if all(product_factors[factor] >= factors[factor] for factor in factors):
                total_ways += 1

    return total_ways

